"""Second-pass human labels. Charts through trigger only. No machine auction/trigger/previous label displayed."""
from __future__ import annotations

from collections import Counter
from typing import Any


def _lab(
    pattern: str,
    opening_state: str,
    opening: str,
    location: str,
    location_kind: str,
    retest: str,
    trigger: str,
    *attrs: str,
    note: str,
    htf_role: str = "contextual",
    late: bool = False,
) -> dict[str, Any]:
    return {
        "sp_pattern": pattern,
        "sp_opening_state": opening_state,
        "sp_opening": opening,
        "sp_location": location,
        "sp_location_kind": location_kind,
        "sp_retest": retest,
        "sp_trigger": trigger,
        "sp_attrs": list(attrs),
        "sp_htf_role": htf_role,
        "sp_late": late,
        "sp_note": note,
        "sp_future_used": False,
    }


def _r(
    pattern: str,
    state: str,
    opening: str,
    loc: str,
    kind: str,
    retest: str,
    trig: str,
    note: str,
    *attrs: str,
    late: bool = False,
) -> dict[str, Any]:
    return _lab(pattern, state, opening, loc, kind, retest, trig, *attrs, note=note, htf_role="contextual", late=late)


