def apply_second_pass(rows: list[dict[str, Any]]) -> dict[str, Any]:
    labeled: list[dict[str, Any]] = []
    missing = 0
    for ev in rows:
        rid = int(ev.get("rca_id") or 0)
        lab = dict(HUMAN_LABELS.get(rid) or {})
        reviewed = bool(lab)
        if not reviewed:
            missing += 1
        labeled.append({**ev, **lab, "sp_reviewed": reviewed})
    n = sum(1 for r in labeled if r.get("sp_reviewed"))
    states = Counter(str(r.get("sp_opening_state")) for r in labeled if r.get("sp_reviewed"))
    kinds = Counter(str(r.get("sp_location_kind")) for r in labeled if r.get("sp_reviewed"))
    patterns = Counter(str(r.get("sp_pattern")) for r in labeled if r.get("sp_reviewed"))
    return {
        "reviewed_n": n,
        "missing_n": missing,
        "universe_n": len(rows),
        "actual_second_pass": missing == 0 and n == len(rows) and n > 0,
        "sp_pattern_counts": dict(patterns),
        "sp_opening_state_counts": dict(states),
        "sp_location_kind_counts": dict(kinds),
        "CLEAR_CONTINUATION": int(patterns.get("CLEAR_CONTINUATION") or 0),
        "QUESTIONABLE": int(patterns.get("QUESTIONABLE") or 0),
        "NOT_CONTINUATION": int(patterns.get("NOT_CONTINUATION") or 0),
        "rows": labeled,
        "future_used": False,
    }
